// Check if lookahead buffer is enabled
if (lfs->cfg->lookahead_size == 0) {
    // No lookahead buffer, use simple allocation
    for (lfs_block_t block = 0; block < lfs->block_count; block++) {
        if (lfs->free_queue[block >> 3] & (1 << (block & 7))) {
            lfs->free_queue[block >> 3] &= ~(1 << (block & 7));
            *block = block;
            return LFS_ERR_OK;
        }
    }
    return LFS_ERR_NOSPC;
}

// Lookahead buffer is enabled
lfs_block_t *lookahead = static_cast<lfs_block_t*>(lfs->cfg->lookahead_buffer);
std::memset(lookahead, 0, lfs->cfg->lookahead_size);

lfs_block_t best_block = LFS_BLOCK_NULL;
lfs_block_t best_wear = 0xFFFFFFFF;
lfs_block_t best_erase = 0xFFFFFFFF;
lfs_block_t best_lookahead = 0;

lfs_block_t lookahead_start = lfs->lookahead_pos;
lfs_block_t lookahead_end = lookahead_start + (lfs->cfg->lookahead_size * 8) - 1;
if (lookahead_end >= lfs->block_count) {
    lookahead_end = lfs->block_count - 1;
}

lfs_block_t lookahead_count = 0;

// First pass: find blocks in lookahead range
for (lfs_block_t block = lookahead_start; block <= lookahead_end; block++) {
    if (lfs->free_queue[block >> 3] & (1 << (block & 7))) {
        lookahead[lookahead_count++] = block;
        if (lookahead_count >= lfs->cfg->lookahead_size * 8) {
            break;
        }
    }
}

// Second pass: find blocks outside lookahead range
if (lookahead_count < lfs->cfg->lookahead_size * 8) {
    for (lfs_block_t block = 0; block < lfs->block_count; block++) {
        if (block < lookahead_start || block > lookahead_end) {
            if (lfs->free_queue[block >> 3] & (1 << (block & 7))) {
                lookahead[lookahead_count++] = block;
                if (lookahead_count >= lfs->cfg->lookahead_size * 8) {
                    break;
                }
            }
        }
    }
}

// Find best block with wear leveling
for (lfs_block_t i = 0; i < lookahead_count; i++) {
    lfs_block_t block = lookahead[i];
    lfs_block_t wear = lfs->block_erase_count[block];
    lfs_block_t erase = lfs->block_erase_count[block];

    // Prefer blocks with lower erase count
    if (erase < best_erase) {
        best_block = block;
        best_erase = erase;
        best_wear = wear;
        best_lookahead = i;
    }
    // If same erase count, prefer blocks with lower wear
    else if (erase == best_erase && wear < best_wear) {
        best_block = block;
        best_wear = wear;
        best_lookahead = i;
    }
}

// If no block found, return no space
if (best_block == LFS_BLOCK_NULL) {
    return LFS_ERR_NOSPC;
}

// Mark block as allocated
lfs->free_queue[best_block >> 3] &= ~(1 << (best_block & 7));

// Update wear leveling information
if (lfs->cfg->block_cycles > 0) {
    lfs->block_erase_count[best_block]++;
}

// Update lookahead position
lfs->lookahead_pos = (best_lookahead + 1) % (lfs->cfg->lookahead_size * 8);

*block = best_block;
return LFS_ERR_OK;

